import type { ComponentProps, ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { Breadcrumbs, type BreadcrumbItem } from '../../navigation/Breadcrumbs'
import styles from './PageHeading.module.css'

export interface PageHeadingProps extends Omit<ComponentProps<'header'>, 'title'> {
  title: ReactNode
  /** One or two lines under the title. */
  description?: ReactNode
  /** Where this page sits. Rendered above the title. */
  breadcrumbs?: BreadcrumbItem[]
  /** Short facts about the page's subject: a status, a date, an owner. Each may start with an icon. */
  meta?: ReactNode[]
  /** Buttons at the end of the title row. They wrap under the title on narrow screens. */
  actions?: ReactNode
  /** A Tabs element under the heading, for sections of the same page. */
  tabs?: ReactNode
  /** The page's own heading is h1; use 2 when the heading sits inside a larger page. */
  headingLevel?: 1 | 2
}

/**
 * The top of a page: where it is, what it is, and what you can do with it.
 * Built from Breadcrumbs and whatever buttons and Tabs you pass in.
 */
export function PageHeading({
  title,
  description,
  breadcrumbs,
  meta,
  actions,
  tabs,
  headingLevel = 1,
  className,
  ...props
}: PageHeadingProps) {
  const Heading = `h${headingLevel}` as const
  return (
    <header className={cn(styles.pageHeading, tabs != null && tabs !== false && styles.withTabs, className)} {...props}>
      {breadcrumbs && <Breadcrumbs items={breadcrumbs} size="sm" className={styles.breadcrumbs} />}
      <div className={styles.row}>
        <div className={styles.text}>
          <Heading className={styles.title}>{title}</Heading>
          {description && <p className={styles.description}>{description}</p>}
          {meta && meta.length > 0 && (
            <ul className={styles.meta}>
              {meta.map((item, i) => (
                <li key={i}>{item}</li>
              ))}
            </ul>
          )}
        </div>
        {actions && <div className={styles.actions}>{actions}</div>}
      </div>
      {tabs}
    </header>
  )
}

.pageHeading {
  display: grid;
  gap: var(--space-3);
  padding-block-end: var(--space-6);
  border-block-end: 1px solid var(--border);
  font-family: var(--font-sans);
  color: var(--foreground);
}

/* With tabs, the tab list's own underline is the bottom edge. */
.withTabs {
  gap: var(--space-4);
  padding-block-end: 0;
  border-block-end: 0;
}

.breadcrumbs {
  margin-block-end: var(--space-1);
}

/* Title and actions share a row while there is room; the actions drop
   under the title when there is not, rather than squeezing it. */
.row {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-4);
}

.text {
  display: grid;
  gap: var(--space-2);
  flex: 1 1 20rem;
  min-inline-size: 0;
}

.title {
  margin: 0;
  font-size: var(--text-heading-xl);
  line-height: var(--leading-heading-xl);
  font-family: var(--font-heading);
  font-weight: 500;
  overflow-wrap: anywhere;
}

.description {
  margin: 0;
  max-inline-size: 65ch;
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--muted-foreground);
}

.meta {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2) var(--space-6);
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--muted-foreground);
}

.meta > li {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1-5);
}

.meta > li > :global(svg) {
  flex-shrink: 0;
  font-size: var(--space-4);
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}
